/**
 * GitHub showcase data. The JSON is generated by `npm run github:sync`
 * (scripts/sync-github.mjs) and committed, so the static export never calls
 * the GitHub API. Only public, non-fork repos make it into the file.
 */
import data from './github.json'

/**
 * Short descriptions for repos whose GitHub description is empty or too long
 * for a table row. Taken from each repo's README.
 */
const blurbs = {
  'django-aws-etl':
    'Event-driven ETL for healthcare CSV drops: S3 event, SQS queue, Celery worker, Postgres. Runs locally on LocalStack.',
  'fhir-summary-gpt':
    'CLI that turns structured patient data into a readable health summary with an LLM, then exports Word or PDF via Pandoc.',
  'developer-directory':
    'Developer profile CRUD app: Go (Gin, GORM, SQLite, Swagger) backend with an Angular and Tailwind front end.',
  'agentic-nestjs-react-postgres':
    'Docker-based starter: NestJS and TypeORM API, React front end, Postgres, one `make setup` to run.',
  'gpt-engine':
    'Framework for session memory, tool orchestration and pluggable providers around GPT-class models.',
  bege: 'Browser tool for making clean, themed code screenshots. Live demo on GitHub Pages.',
  'tiktok-to-youtube-automation':
    'Downloads TikTok clips with metadata and republishes them as YouTube Shorts.',
  'shopify-christmas-theme-demo':
    'Holiday storefront on Shopify Hydrogen with React Router 7, TypeScript and Tailwind.',
  lightcord: 'Small TypeScript client for the Discord and Twitch chat APIs.',
  ClutchKey: 'C++ audio manager built to sit behind a Stream Deck.',
  'ng-isbn-validator': 'ISBN validation for Angular, usable as a plain module too.',
  BetterRaidBuffs: 'WoW addon: spell ranks, stacking buffs and same-class auras on compact raid frames.',
  WarlockTaxi: 'WoW addon that runs a summoning network: register, share status and fee, request a ride.',
  'vdpets-unity': 'Virtual desktop pets in Unity.',
  'scottsdevelopment.com': 'This site. Next.js static export on S3 and CloudFront.',
}

/** Loose grouping used for the table's "area" column. */
const areas = {
  'django-aws-etl': 'Healthcare data',
  'fhir-summary-gpt': 'Healthcare data',
  'agentic-nestjs-react-postgres': 'Full stack',
  'developer-directory': 'Full stack',
  'gpt-engine': 'LLM tooling',
  bege: 'Developer tools',
  'tiktok-to-youtube-automation': 'Automation',
  'shopify-christmas-theme-demo': 'E-commerce',
  lightcord: 'Chat APIs',
  ClutchKey: 'Desktop',
  'ng-isbn-validator': 'Libraries',
  BetterRaidBuffs: 'Game addons',
  WarlockTaxi: 'Game addons',
  'vdpets-unity': 'Desktop',
  'scottsdevelopment.com': 'Web',
}

export const profile = data.profile
export const generatedAt = data.generatedAt

export function featuredRepos(source = data.repos) {
  return source.map((r) => ({
    ...r,
    blurb: blurbs[r.name] || r.description,
    area: areas[r.name] || 'Other',
  }))
}

export function formatPushed(iso) {
  const d = new Date(iso)
  return d.toLocaleDateString('en-US', { month: 'short', year: 'numeric', timeZone: 'UTC' })
}
